-- ============================================================================
-- Recording ledger columns are not updatable through an entity save (MJ#6010)
-- ============================================================================
-- WHY THIS EXISTS. The seven recording-ledger columns of AIAgentSession (RecordingStatus,
-- RecordingExpectedShards, RecordingCapturedSamples, RecordingGaps, RecordingAssemblyVersion,
-- RecordingFileID, RecordingMedia) are written by the ledger's stored procedures while a session is
-- live (V202610151535__v6.2.x__Realtime_Recording_Shard_Ledger.sql). A session copy loaded before one
-- of those procs ran and saved after it (the close, a heartbeat) sent `@<Field>_Clear=1` for every
-- column that was NULL in memory, so spUpdateAIAgentSession wiped the terminal stamp: a complete
-- recording was deferred and forced to Partial 90 s later. The old guard lived in an entity subclass
-- (MJAIAgentSessionEntityServer.Save), which an app that registers its own session class replaces.
--
-- The fix moves the rule into metadata: metadata/entities/.ai-agent-session-recording-ledger-fields.json
-- sets AllowUpdateAPI=0 on the seven fields, so CodeGen leaves them (and their _Clear companions) out of
-- spUpdateAIAgentSession below, and no entity class can write them. RecordingStartedAt stays updatable.
--
-- The two legitimate writers of RecordingFileID / RecordingMedia (the end-of-call upload and the
-- recording-start stamp) now call spStampAIAgentSessionRecordingFile, defined here. Same style as the
-- other ledger procs: one statement, granted to the runtime roles, which hold no table-level DML.
--
-- DEPLOY ORDER. This migration replaces spCreate/spUpdateAIAgentSession without the seven parameters,
-- but the AllowUpdateAPI=0 flags arrive only through `mj sync push` of the metadata. Until they land
-- (and MJAPI reloads its metadata), every MJ: AI Agent Sessions save sends parameters the procs no
-- longer accept and fails. Apply this migration and push the metadata together (the release's
-- consolidated Metadata_Sync migration does this; a dev database migrated from `next` must run
-- `mj sync push --dir=metadata` right after `mj migrate`).
--
-- PostgreSQL counterpart is produced by the release build.
-- ============================================================================

SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- Stamps a session's recording file, media kind and t0. Each NULL parameter leaves its column as stored,
-- so a caller writes only what it knows. Returns one row with the session's RecordingStatus after the
-- write, or no row when the session does not exist (the caller treats that as an error).
CREATE PROCEDURE [${flyway:defaultSchema}].[spStampAIAgentSessionRecordingFile]
    @AgentSessionID UNIQUEIDENTIFIER,
    @RecordingFileID UNIQUEIDENTIFIER = NULL,
    @RecordingMedia NVARCHAR(20) = NULL,
    @RecordingStartedAt DATETIMEOFFSET = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Stamped TABLE ([RecordingStatus] NVARCHAR(20));
    UPDATE [${flyway:defaultSchema}].[AIAgentSession]
       SET [RecordingFileID] = ISNULL(@RecordingFileID, [RecordingFileID]),
           [RecordingMedia] = ISNULL(@RecordingMedia, [RecordingMedia]),
           [RecordingStartedAt] = ISNULL(@RecordingStartedAt, [RecordingStartedAt])
    OUTPUT inserted.[RecordingStatus] INTO @Stamped
     WHERE [ID] = @AgentSessionID;
    SELECT [RecordingStatus] FROM @Stamped;
END;
GO
GRANT EXECUTE ON [${flyway:defaultSchema}].[spStampAIAgentSessionRecordingFile] TO [cdp_Developer], [cdp_Integration];
GO


















































